<?php
require __DIR__.'/config/config.php';
require_login();
if ($_SERVER['REQUEST_METHOD'] === 'POST') { check_csrf(); $action = $_POST['action'] ?? 'create'; if ($action === 'delete') { $statement = db()->prepare('DELETE FROM categories WHERE id=?'); $statement->execute([(int) $_POST['id']]); } elseif ($action === 'update') { $statement = db()->prepare('UPDATE categories SET name=?,description=? WHERE id=?'); $statement->execute([trim($_POST['name']), trim($_POST['description'] ?: null), (int) $_POST['id']]); } else { $statement = db()->prepare('INSERT INTO categories (name,description) VALUES (?,?)'); $statement->execute([trim($_POST['name']), trim($_POST['description'] ?: null)]); } redirect('/categories.php'); }
$categories = db()->query('SELECT * FROM categories ORDER BY id DESC')->fetchAll();
$editCategory = null;
if (isset($_GET['edit'])) { $statement = db()->prepare('SELECT * FROM categories WHERE id=?'); $statement->execute([(int) $_GET['edit']]); $editCategory = $statement->fetch(); }
?>
<!doctype html><html lang="vi"><head><meta charset="utf-8"><title>Danh mục</title><link rel="stylesheet" href="<?= BASE_URL ?>/style.css"></head><body><header class="topbar"><strong>NHÀ SÁCH TRÍ TUỆ</strong><a href="<?= BASE_URL ?>/index.php">Dashboard</a></header><main class="container"><h1>Danh mục</h1><section class="panel"><h2><?= $editCategory ? 'Sửa danh mục' : 'Thêm danh mục' ?></h2><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="<?= $editCategory ? 'update' : 'create' ?>"><?php if ($editCategory): ?><input type="hidden" name="id" value="<?= $editCategory['id'] ?>"><?php endif; ?><label>Tên danh mục<input name="name" value="<?= e($editCategory['name'] ?? '') ?>" required></label><label>Mô tả<input name="description" value="<?= e($editCategory['description'] ?? '') ?>"></label><button><?= $editCategory ? 'Lưu thay đổi' : 'Thêm danh mục' ?></button></form></section><section class="panel"><table><tr><th>Tên</th><th>Mô tả</th><th>Thao tác</th></tr><?php foreach ($categories as $category): ?><tr><td><?= e($category['name']) ?></td><td><?= e($category['description']) ?></td><td><a class="button small" href="<?= BASE_URL ?>/categories.php?edit=<?= $category['id'] ?>">Sửa</a></td></tr><?php endforeach; ?></table></section></main></body></html>
